+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Weather Forecast</title>
+    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.2.3/dist/css/bootstrap.min.css">
+    <style>
+        body {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            font-family: 'Inter', sans-serif;
+        }
+        .container {
+            display: flex;
+            flex-direction: column;
+            gap: 16px;
+            width: 100%;
+            max-width: 460px;
+            padding: 24px;
+            background: rgba(16, 24, 40, 0.5);
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .header {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .header h1 {
+            font-family: 'JetBrains Mono', monospace;
+            font-size: 24px;
+            color: #fff;
+        }
+        .header h1 span {
+            color: #38bdf8;
+        }
+    </style>
+</head>
+<body>
+    <div class="container">
+        <div class="header">
+            <h1>Weather <span>Forecast</span></h1>
+        </div>
+        <div class="card">
+            <div class="card-body">
+                <h5 class="card-title">Current Weather</h5>
+                <p class="card-text">Temperature: <span id="temperature">--</span>°C</p>
+                <p class="card-text">Humidity: <span id="humidity">--</span>%</p>
+                <p class="card-text">Wind Speed: <span id="wind-speed">--</span> km/h</p>
+            </div>
+        </div>
+        <div class="card">
+            <div class="card-body">
+                <h5 class="card-title">Forecast</h5>
+                <p class="card-text">Today: <span id="today-forecast">--</span></p>
+                <p class="card-text">Tomorrow: <span id="tomorrow-forecast">--</span></p>
+            </div>
+        </div>
+    </div>
+    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.2.3/dist/js/bootstrap.bundle.min.js"></script>
+    <script>
+        // API endpoint for weather data
+        const apiEndpoint = 'https://api.openweathermap.org/data/2.5/weather';
+        const forecastEndpoint = 'https://api.openweathermap.org/data/2.5/forecast';
+        const apiKey = 'YOUR_OPENWEATHERMAP_API_KEY';
+        const city = 'London';
+        
+        // Get current weather data
+        fetch(`${apiEndpoint}?q=${city}&appid=${apiKey}&units=metric`)
+            .then(response => response.json())
+            .then(data => {
+                document.getElementById('temperature').innerText = data.main.temp;
+                document.getElementById('humidity').innerText = data.main.humidity;
+                document.getElementById('wind-speed').innerText = data.wind.speed;
+            });
+        
+        // Get forecast data
+        fetch(`${forecastEndpoint}?q=${city}&appid=${apiKey}&units=metric`)
+            .then(response => response.json())
+            .then(data => {
+                const todayForecast = data.list[0].weather[0].description;
+                const tomorrowForecast = data.list[8].weather[0].description;
+                document.getElementById('today-forecast').innerText = todayForecast;
+                document.getElementById('tomorrow-forecast').innerText = tomorrowForecast;
+            });
+    </script>
+</body>
+</html>

